# MODEL
set CATS;
param T integer > 0;
set YEARS  := 1..T;
set YEARS0 := 0..T;
param strength      {CATS} >= 0;
param requirement   {CATS, YEARS} >= 0;
param lessonewaste  {CATS} >= 0, <= 1;
param moreonewaste  {CATS} >= 0, <= 1;
param recruit_cap   {CATS} >= 0;
param shorttime_cap >= 0;
param overman_cap   >= 0;
param retrain_u_semi_cap  >= 0;
param retrain_semi_s_frac >= 0, <= 1;
param costredundancy {CATS} >= 0;
param costoverman    {CATS} >= 0;
param costshort      {CATS} >= 0;
param costretrain_u_semi >= 0;
param costretrain_semi_s >= 0;
var t {CATS, YEARS0} >= 0;
var u {CATS, YEARS}  >= 0;
var w {CATS, YEARS}  >= 0;
var x {CATS, YEARS}  >= 0;
var y {CATS, YEARS}  >= 0;
var v_u_semi {YEARS} >= 0;
var v_semi_s {YEARS} >= 0;
var r_s_semi {YEARS} >= 0;
var r_s_u    {YEARS} >= 0;
var r_semi_u {YEARS} >= 0;
minimize TotalCost:
  sum {yr in YEARS} (
      costretrain_u_semi * v_u_semi[yr]
    + costretrain_semi_s * v_semi_s[yr]
    + sum {c in CATS} ( costredundancy[c] * w[c,yr]
                      + costshort[c]      * x[c,yr]
                      + costoverman[c]    * y[c,yr] )
  );
subject to InitStrength {c in CATS}: t[c,0] = strength[c];
subject to RecruitCap {c in CATS, yr in YEARS}: u[c,yr] <= recruit_cap[c];
subject to ShortCap {c in CATS, yr in YEARS}: x[c,yr] <= shorttime_cap;
subject to OvermanCap {yr in YEARS}: sum {c in CATS} y[c,yr] <= overman_cap;
subject to MeetRequirement {c in CATS, yr in YEARS}: t[c,yr] - y[c,yr] - 0.5*x[c,yr] = requirement[c,yr];
subject to RetrainUSemiCap {yr in YEARS}: v_u_semi[yr] <= retrain_u_semi_cap;
subject to RetrainSemiToSkilledLimit {yr in YEARS}: v_semi_s[yr] <= retrain_semi_s_frac * t[3,yr];
subject to BalanceSkilled {yr in YEARS}: t[3,yr] = (1 - moreonewaste[3]) * t[3,yr-1] + (1 - lessonewaste[3]) * u[3,yr] + (1 - moreonewaste[3]) * v_semi_s[yr] - r_s_semi[yr] - r_s_u[yr] - w[3,yr];
subject to BalanceSemi {yr in YEARS}: t[2,yr] = (1 - moreonewaste[2]) * t[2,yr-1] + (1 - lessonewaste[2]) * u[2,yr] + (1 - moreonewaste[2]) * v_u_semi[yr] - v_semi_s[yr] + 0.5 * r_s_semi[yr] - r_semi_u[yr] - w[2,yr];
subject to BalanceUnskilled {yr in YEARS}: t[1,yr] = (1 - moreonewaste[1]) * t[1,yr-1] + (1 - lessonewaste[1]) * u[1,yr] - v_u_semi[yr] + 0.5 * r_s_u[yr] + 0.5 * r_semi_u[yr] - w[1,yr];

# DATA
