set CATS := 1 2 3;
param strength := 1 2000, 2 1500, 3 1000;
param requirement : 1 2 3 := 1 1000 500 0, 2 1400 2000 2500, 3 1000 1500 2000;
param lessonewaste := 1 0.25, 2 0.20, 3 0.10;
