# Model for Economic Planning (Dynamic Leontief), Variant 2

set I;

param T;
param H;

set Y0  := 0..T+1;
set Ybal := 0..H;
set Yy  := 2..T+1;

param C  {I, I};
param D  {I, I};
param mx {I};
param my {I};
param cap0   {I};
param stock0 {I};
param M;

var x {i in I, t in Y0} >= 0;
var s {i in I, t in Y0} >= 0;
var y {i in I, t in Yy} >= 0;

maximize Total_Output_Final_Years:
  sum {i in I} (x[i,T-1] + x[i,T]);

subject to InitStock {i in I}: s[i,0] = stock0[i];
subject to NoProductionYear0 {i in I}: x[i,0] = 0;
subject to NoCapacityAfterYearT {i in I}: y[i,T+1] = 0;
subject to TerminalStock {i in I}: s[i,T+1] = s[i,T];

subject to CapacityLimit {i in I, t in Y0}:
  x[i,t] <= cap0[i] + sum {tt in Yy: tt <= t} y[i,tt];

# Balance constraints (for use_exo=0)
subject to Balance {i in I, t in Ybal}:
  x[i,t] + s[i,t]
  = sum {j in I} C[i,j] * x[j,t+1]
    + sum {j in I} D[i,j] * (if t+2 in Yy then y[j,t+2] else 0)
    + s[i,t+1];

# Manpower constraint (for enforce_manpower=1)
subject to ManpowerCap {t in Ybal}:
  sum {j in I} mx[j] * x[j,t+1]
  + sum {j in I} my[j] * (if t+2 in Yy then y[j,t+2] else 0)
  <= M;


// -------- Corrected Data (.dat) --------

